-- cobus-visser-international-centurion-golf-estate (researched)
UPDATE businesses SET description = 'Cobus Visser International is a consulting firm based in Centurion Golf Estate, working across business upscaling, organisational cohesion and leadership empowerment through keynote talks, firewalking events and coaching programmes. The firm says its firewalking events alone have been part of a transformational experience for more than 13,000 people, while its keynote talks have reached audiences in the tens of thousands. Cobus Visser International describes its business-solutions work as contributing, directly and indirectly, to the creation and growth of around 8,000 jobs across a range of industries and countries. Its client work spans both corporate organisations and start-ups, combining business-scaling support with leadership training intended to build cohesion within a company rather than focusing on individual performance alone. The firm has delivered keynote talks, firewalking events and training experiences not only across South Africa but also internationally, including in Sweden, Hungary, Mexico, Bali, the United States, Slovakia, the Czech Republic and New Zealand. Based in Centurion Golf Estate, Cobus Visser International positions itself as a consulting practice built around transformational, experience-led methods rather than conventional classroom-style business training alone.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://cobusvisser.com/'), description_enriched_at = datetime('now') WHERE slug = 'cobus-visser-international-centurion-golf-estate' AND description = 'Cobus Visser International offers keynote talks, firewalking events, and business-scaling and leadership training, with clients across South Africa and abroad including Sweden, Mexico and the USA.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- colbyn-electrical-services-colbyn (researched)
UPDATE businesses SET description = 'Colbyn Electrical Services cc. is an electrical contracting business based in Colbyn, Pretoria, that has operated in the electrical industry since the 1980s. The company specialises in designing and installing electrical systems for the retail industry, with a particular focus on lighting effects for display windows, restaurants, shopping malls and office spaces, aiming to bring products and spaces to life through subtle, well-planned illumination. Its electricians are accredited to the SABS SANS 10142-1 standard, reflecting formal recognition as master electricians rather than general handymen. Colbyn Electrical Services keeps teams on standby to meet client needs around the clock, structuring its availability around client project schedules as well as emergencies and unplanned breakdowns. By combining retail lighting design work with round-the-clock availability for urgent electrical issues, the company positions itself to serve both planned installation projects and reactive emergency callouts from the same team. Based in Colbyn, Colbyn Electrical Services treats electricity as an essential service, serving retail, hospitality and office clients across Pretoria who need both specialised lighting installation and responsive general electrical support.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.colbynelectrical.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'colbyn-electrical-services-colbyn' AND description = 'Colbyn Electrical Services is an electrical contracting company in Colbyn, Pretoria, incorporated in 2001 and registered with the Department of Labour and the Electrical Contracting Board.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- connectd-digital-solutions-akasia (researched)
